def solution(input_str):
    """
    Find the longest common subsequence of s1 and s2 that doesn't contain virus as a substring.

    Args:
        input_str: String containing three lines: s1, s2, virus

    Returns:
        The longest valid common subsequence, or "0" if none exists
    """
    lines = input_str.strip().split('\n')
    s1 = lines[0]
    s2 = lines[1]
    virus = lines[2]

    m, n, v_len = len(s1), len(s2), len(virus)

    # Build KMP failure function for virus
    def build_lps(pattern):
        lps = [0] * len(pattern)
        length = 0
        i = 1
        while i < len(pattern):
            if pattern[i] == pattern[length]:
                length += 1
                lps[i] = length
                i += 1
            else:
                if length != 0:
                    length = lps[length - 1]
                else:
                    lps[i] = 0
                    i += 1
        return lps

    # Return new matched length in virus after appending character
    def match_state(current_state, char):
        if current_state < v_len:
            while True:
                prefix_len = current_state
                while prefix_len > 0 and virus[prefix_len] != char:
                    prefix_len = prefix_lps[prefix_len - 1]
                if virus[prefix_len] == char:
                    return prefix_len + 1
                else:
                    if prefix_len == 0:
                        break
                    prefix_len = 0
                if virus[0] != char:
                    break
            if virus[0] == char:
                return 1
            return 0
        return 0

    # Actually rebuild with proper KMP transition
    prefix_lps = build_lps(virus) if v_len > 0 else []

    def get_next_state(state, char):
        # KMP transition: start from current state and find next match
        if state == v_len:
            return 0  # Full match - invalid, but we won't take this path
        while True:
            if state < v_len and virus[state] == char:
                return state + 1
            if state == 0 or virus[state - 1] != char:
                if state == 0:
                    if virus[0] == char:
                        return 1
                    return 0
                state = prefix_lps[state - 1]
            elif state > 0:
                state = prefix_lps[state - 1]
        if virus[0] == char:
            return 1
        return 0

    # DP: dp[i][j][k] = max length LCS using s1[:i] and s2[:j] with virus match state k
    INF = -1e9
    dp = [[[INF] * (v_len + 1) for _ in range(m + 2)] for _ in range(n + 2)]
    from_left_to_right = [[[False] * (v_len + 1) for _ in range(m + 2)] for _ in range(n + 2)]
    from_s1 = [[[False] * (v_len + 1) for _ in range(m + 2)] for _ in range(n + 2)]
    from_s2 = [[[False] * (v_len + 1) for _ in range(m + 2)] for _ in range(n + 2)]

    # Base case
    dp[0][0][0] = 0

    for i in range(m + 1):
        for j in range(n + 1):
            for k in range(v_len):  # k is virus match state (0 to v_len-1)
                if dp[i][j][k] == INF:
                    continue

                # Option 1: don't include s1[i] and s2[j]
                if i < m:
                    if dp[i+1][j][k] < dp[i][j][k]:
                        dp[i+1][j][k] = dp[i][j][k]
                        from_s1[i+1][j][k] = True
                if j < n:
                    if dp[i][j+1][k] < dp[i][j][k]:
                        dp[i][j+1][k] = dp[i][j][k]
                        from_s2[i][j+1][k] = True

                # Option 2: if s1[i] == s2[j], try to include
                if i < m and j < n and s1[i] == s2[j]:
                    new_k = get_next_state(k, s1[i])
                    if new_k != v_len:
                        if dp[i+1][j+1][new_k] < dp[i][j][k] + 1:
                            dp[i+1][j+1][new_k] = dp[i][j][k] + 1
                            from_from_left_to_right[i+1][j+1][new_k] = True

    # Find the answer
    max_len = 0
    best_state = 0
    for k in range(v_len):
        if dp[m][n][k] > max_len:
            max_len = dp[m][n][k]
            best_state = k

    if max_len == 0:
        return "0"

    # Reconstruct the solution
    result = []
    i, j, k = m, n, best_state

    while i > 0 or j > 0:
        if i <= 0 and j <= 0:
            break

        if i > 0 and dp[i][j][k] == dp[i-1][j][k] and from_left[i][j][k]:
            i -= 1
            continue

        if j > 0 and dp[i][j][k] == dp[i][j-1][k] and from_s2[i][j][k]:
            j -= 1
            continue

        # Include the character
        if i > 0 and j > 0:
            prev_k = k
            if v_len > 0:
                while True:
                    if prev_k < v_len and virus[prev_k] == s1[i-1]:
                        prev_k -= 1
                        break
                    if prev_k == 0:
                        break
                    prev_k = prefix_lps[prev_k - 1]
            if prev_k == -1:
                prev_k = 0
            prev_k = prev_k + 1
            k = prev_k  # This was the old state

        # Go back
        i -= 1
        j -= 1
        result.append(s1[i])

    result.reverse()
    return ''.join(result)

