def solution(input_str):
    input_str = input_str.strip()
    lines = input_str.split('\n')

    n, m = map(int, lines[0].split())

    if m == 0:
        return '0'

    # Parse events into phases (groups between type 1 events)
    phases = []  # Each phase is a list of friends
    current_phase = 0

    for i in range(1, len(lines)):
        parts = lines[i].split()
        if parts[0] == '1':
            # Start new phase
            phases.append([])
        else:
            # Friend s visits
            friend = parts[1]
            phases[current_phase].append(friend)

    # Get all unique friends and map to indices
    all_friends = sorted(set(friend for phase in phases for friend in phase))
    friend_to_idx = {f: i for i, f in enumerate(all_friends)}
    num_friends = len(friend_to_idx)

    if num_friends == 0:
        return '0'

    # Build conflict graph
    # Two friends conflict if they appear in the same phase
    conflict = [[False] * num_friends for _ in range(num_friends)]

    for phase in phases:
        friends_in_phase = []
        for f in phase:
            if f in friend_to_idx:
                friends_in_phase.append(friend_to_idx[f])

        for i in range(len(friends_in_phase)):
            for j in range(i + 1, len(friends_in_phase)):
                conflict[friends_in_phase[i]][friends_in_phase[j]] = True
                conflict[friends_in_phase[j]][friends_in_phase[i]] = True

    # Find maximum independent set using DFS with pruning
    best = 0

    def dfs(idx, count, current_mask):
        nonlocal best

        # Pruning: if even picking all remaining friends won't beat best, return
        if count + (num_friends - idx) <= best:
            return

        # If we've considered all friends
        if idx == num_friends:
            best = max(best, count)
            return

        # Option 1: Don't include friend[idx]
        dfs(idx + 1, count, current_mask)

        # Option 2: Include friend[idx] if no conflict
        valid = True
        for i in range(idx):
            if ((current_mask >> i) & 1) and conflict[idx][i]:
                valid = False
                break

        if valid:
            dfs(idx + 1, count + 1, current_mask | (1 << idx))

    dfs(0, 0, 0)

    return str(best)

