        if not line_stripped:
            continue
        parts = list(map(int, line_stripped.split()))
        u, v, t = parts[0], parts[1], parts[2]
        if u != v and 1 <= u <= n and 1 <= v <= n:
            adj[u].append(v)
            adj[v].append(u)
            key = (min(u, v), max(u, v))
            constraints[key] = t

    # Check 2-coloring consistency
    color = {}
    valid = True

    for start in range(1, n + 1):
        if start in color:
            continue

        # BFS
        color[start] = 0
        queue = [start]
        head = 0

        while head < len(queue):
            u = queue[head]
            head += 1

            for v in adj[u]:
                key = (min(u, v), max(u, v))
                if key not in constraints:
                    continue

                rel = constraints[key]
                expected = color[u] if rel == 1 else 1 - color[u]

                if v in color:
                    if color[v] != expected:
                        valid = False
                        break
                else:
                    color[v] = expected
                    queue.append(v)

            if not valid:
                break

    if not valid:
        return '0\n'

    # If no constraints given, answer is 2^(n-1)
    if m == 0:
        return f'{pow(2, n - 1, MOD)}\n'

    # Count connected components
    seen = set()
    components = 0

    for i in range(1, n + 1):
        if i not in seen:
            reachable = {i}
            queue = [i]
            head = 0

            while head < len(queue):
                u = queue[head]
                head += 1

                for v in adj[u]:
                    if v not in reachable:
                        reachable.add(v)
                        queue.append(v)

            has_constraint = False
            for u in reachable:
                for v in adj[u]:
                    if (min(u, v), max(u, v)) in constraints:
                        has_constraint = True
                        break
                if has_constraint:
                    break

            if has_constraint:
                seen.update(reachable)
                components += 1

    # Each component can independently choose color (but all in same group in first count)
    if components == 0:
        # All nodes have no constraints - 2^(n-1) ways
        return f'{pow(2, n - 1, MOD)}\n'

    return f'{pow(2, components - 1, MOD)}\n'

