def compute_distances(n, adj):
    """BFS from each node to compute all distances"""
    distances = [[0] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        dist = [-1] * (n + 1)
        dist[start] = 0
        q = [start]

        while q:
            u = q[0]
            q.pop(0)
            distances[start][u] = dist[u]

            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)

    return distances


def brute_force(n, adj):
