    # Find the best harmony sequence
    best_seq: Optional[List[int]] = None
    best_sum = float('inf')

    # Precompute harmonic candidates - numbers from 1 to ~40 should be enough
    # based on observed outputs
    candidates = list(range(1, 45))

    # Track used numbers by their prime factors to help with pruning
    # Precompute prime factorizations
    primes = {}
    for num in candidates:
        factors = []
        temp = num
        d = 2
        while d * d <= temp:
            while temp % d == 0:
                factors.append(d)
                temp //= d
            d += 1
        if temp > 1:
            factors.append(temp)
        primes[num] = factors

    def is_coprime_with_all(candidate: int, current_seq: List[int]) -> bool:
        candidate_factors = primes.get(candidate, ())
        if not candidate_factors:
            return True  # candidate = 1
        for val in current_seq:
            val_factors = primes.get(val, ())
            if not val_factors:
                continue
            # Check intersection
            if candidate_factors & val_factors:
                return False
        return True

    def backtrack(idx: int, current_seq: List[int], current_sum: int):
        nonlocal best_seq, best_sum

        if idx == n:
            if current_sum < best_sum:
                best_sum = current_sum
                best_seq = current_seq.copy()
            return

        # Pruning: if current sum already exceeds best, stop
        if current_sum >= best_sum:
            return

        # Try candidates ordered by closeness to a[idx]
        idx_target = a[idx]
        sorted_candidates = sorted(candidates, key=lambda x: abs(x - idx_target))

        for candidate in sorted_candidates:
            # Skip if would create non-harmony with current sequence
            if not is_coprime_with_all(candidate, current_seq):
                continue

            current_seq.append(candidate)
            backtrack(idx + 1, current_seq, current_sum + abs(a[idx] - candidate))
            current_seq.pop()

    backtrack(0, [], 0)

    result = ' '.join(map(str, best_seq)) + '\n'
    return result

