    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    transformers = []
    for i in range(1, k+1):
        parts = lines[i].split()
        x, y, d, t, e = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
        transformers.append((x, y, d, t, e))

    # Map (r, c) -> cost at time t = r + c
    cell_costs = {}
    for (x, y, d, start_t, cost) in transformers:
        for t in range(start_t, n + m - 1):
            phase = (t - start_t) % 4
            r = x + d * [(0, 1)][phase].index(1)
            c = y + d * [0, -1, 0, 1][phase]
            key = (r, c)
            if key not in cell_costs:
                cell_costs[key] = 0
            cell_costs[key][t] += cost

    # Build position -> [(total_cost, time)] mapping
    pos_times = {}
    for (r, c), costs in cell_costs.items():
        pos_times[(r, c)] = costs

    # DP: dp[r][c] = min energy to reach (r, c)
    dp = [[float('inf')] * m for _ in range(n)]
    dp[0][0] = 0

    for t in range(n + m - 1):
        for r in range(n):
            for c in range(m):
                if r + c != t:
                    continue
                current_cost = 0
                if (r, c) in pos_times:
                    current_cost = pos_times[(r, c)][t]

                dp[r][c] += current_cost

                if r < n - 1:
                    dp[r + 1][c] = min(dp[r + 1][c], dp[r][c])
                if c < m - 1:
                    dp[r][c + 1] = min(dp[r][c + 1], dp[r][c])

    return str(dp[n-1][m-1])

