def solve(n, fibs):
    """
    Count the number of ways to decompose n into distinct Fibonacci numbers.
    """
    memo = {}

    def count(target, start_idx):
        if target == 0:
            return 1
        state = (target, start_idx)
        if state in memo:
            return memo[state]

        if target < 0 or start_idx >= len(fibs):
            return 0

        count = 0
        for i in range(start_idx, len(fibs)):
            if fibs[i] > target:
                break
            count += count(target - fibs[i], i + 1)

        memo[state] = count
        return count

    return count(n, 0)


