from collections import Counter

def solution(s):
    lines = s.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    if n == 0:
        return '0'

    MOD = 10**9 + 7

    def get_sq_free(x):
        res = 1
        d = 2
        while d * d <= x:
            cnt = 0
            while x % d == 0:
                x //= d
                cnt += 1
            if cnt % 2 == 1:
                res *= d
            d += 1 if d == 2 else 2
        if x > 1:
            res *= x
        return res

    groups = Counter()
    for x in arr:
        sf = get_sq_free(x)
        groups[sf] += 1

    sizes = list(groups.values())
    total = 0

    # Precompute factorials and inverse factorials
    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = fact[i-1] * i % MOD

    inv = [1] * (n + 1)
    inv[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n-1, -1, -1):
        inv[i] = inv[i+1] * (i+1) % MOD

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv[k] % MOD * inv[n-k] % MOD

    # dp[size] = count of valid arrangements with 'size' elements from processed groups
    # We'll only track dp[total] since we process group by group
    dp = {0: 1}  # Start with 1 way to arrange 0 elements

    for g in sizes:
        new_dp = {}
        if len(dp) == 0:
            new_dp[g] = 1
        else:
            for total, ways in dp.items():
                # Insert g elements into (total + 1) slots, choosing g distinct slots
                # ways = C(total+1, g) * total! = C(total+1, g) * (total+1)! / (total+1)
                ways_insert = C(total + 1, g)
                if ways_insert > 0:
                    new_total = total + g
                    new_dp[new_total] = (new_dp.get(new_total, 0) + ways * ways_insert) % MOD

        dp = new_dp
        total += g

    result_total = sum(dp.values())
    return str(result_total % MOD)

